sys_script_include.script:
var SaldoFeriasAjax = Class.create();
SaldoFeriasAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getSaldo: function() {
        var maior = 0;
        var gr = new GlideRecord('x_1863045_hr_sel_1_saldo_de_ferias');
        gr.addQuery('colaborador', gs.getUserID());
        gr.query();
        while (gr.next()) {
            var dias = parseInt(gr.getValue('dias_disponiveis'), 10) || 0;
            if (dias > maior) maior = dias;
        }
        return String(maior);
    },

    type: 'SaldoFeriasAjax'
});
